INSERT INTO changelog (title, body, created_at) VALUES ('Заявки: країна і месенджер окремими рядками', 'У повідомленні про заявку відповіді про країну, месенджер (Viber / WhatsApp / Telegram) та інший номер для звʼязку тепер стоять окремими рядками одразу під телефоном (🌍, 💬, 📱). Якщо номер не український, зверху є підказка «перевір месенджер нижче» — для закордонних лідів, у яких месенджер на іншому номері. Система впізнає ці поля за назвою питання у формі (країна, месенджер, номер). Якщо в іншій формі питання назване інакше — скажи, я додам.
Помилка «Meta просить зачекати (ліміт запитів)» більше не падає в Журнал: це не поломка, синхронізація просто повториться за 2 год.
Дублів заявок система не робить: кожна заявка Meta обробляється рівно один раз. Якщо в групі зʼявляються копії — це інший сервіс (наприклад, старе підключення через Zapier/Make/бота) — його треба вимкнути.', datetime('now'));
